<form method="get" class="list-toolbar"><input type="hidden" name="section" value="<?= e($section) ?>"><input type="hidden" name="event_id" value="<?= $studioEventId??0 ?>"><?php if(($_GET['view']??'')==='table'): ?><input type="hidden" name="view" value="table"><?php endif; ?>
