 <?php if($filterGames): ?><label class="sr-only" for="register-game">Game</label><select id="register-game" name="game"><option value="">All games</option><?php foreach($filterGames as $game): ?><option value="<?= e($game['id']) ?>" <?= $gameId===$game['id']?'selected':'' ?>><?= e($game['label']) ?></option><?php endforeach; ?></select><?php endif; ?>
