  <?php endif; ?>
  <details class="studio-disclosure"><summary>Payment history</summary><?php $history=st_finance_query($db,'SELECT r.*,u.display_name FROM az_payment_reviews r LEFT JOIN users u ON u.id=r.staff_id WHERE r.order_id=? ORDER BY r.id DESC',[$r['id']]);foreach($history as $entry): ?><p><strong><?= e(ucfirst($entry['action'])) ?></strong> · <?= e($entry['display_name']??'Coordinator') ?> · <?= e(az_record_date_label($entry['created_at'])) ?><br><?= e($entry['note']) ?></p><?php endforeach; $proofs=st_finance_query($db,'SELECT id,reference,uploaded_at FROM az_payment_proofs WHERE order_id=? ORDER BY id DESC',[$r['id']]);foreach($proofs as $proof): ?><p><a href="/payment-proof-file.php?id=<?= (int)$proof['id'] ?>" target="_blank" rel="noopener">Screenshot <?= e($proof['reference']) ?> ›</a> · <?= e(az_record_date_label($proof['uploaded_at'])) ?></p><?php endforeach;if(!$history&&!$proofs): ?><p class="help">No screenshot submitted yet.</p><?php endif; ?></details>
 <?php elseif($r['provider']==='free'): ?><p class="help">Free registration. No payment review needed.</p><?php else: ?><p class="help">Historical <?= e($r['provider']) ?> payment · <?= e($r['gateway_payment']?:'No recorded payment') ?></p><?php endif; ?>
</div></details>
