<?php $block=st_finance_query($db,'SELECT * FROM az_ticket_blocks WHERE ticket_id=?',[$r['id']])[0]??null;if($block): ?><p class="help">Block reason: <?= e($block['reason']) ?> · <?= e($block['blocked_at']) ?><?= $block['unblocked_at']?' · Unblocked '.e($block['unblocked_at']):'' ?></p><?php endif; ?>
<?php if(cms_can($u,'tickets','revoke')&&in_array($r['status'],['VALID','USED','BLOCKED'],true)): ?><form method="post" class="inline-form"><?php cms_hidden($r['status']==='BLOCKED'?'unblock_ticket':'block_ticket'); ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><label class="field"><span>Reason</span><input name="reason" minlength="3" maxlength="1000" required></label><button class="<?= $r['status']==='BLOCKED'?'quiet-button':'danger-button' ?>" type="submit"><?= $r['status']==='BLOCKED'?'Unblock ticket':'Block ticket' ?></button></form><?php endif; ?>
</div></details><?php endforeach; ?></div>
